#!/usr/bin/env python3
"""Generate finite witnesses for Lean's encoding-count recurrence.

Python is only a certificate generator: each row equation is checked by Lean's
kernel, and EncodingCardinality proves that the recurrence counts encodings.
"""

from pathlib import Path


def generate() -> str:
    lines = [
        "import XmssSecurity.Proof.EncodingCardinality",
        "",
        "/-! Generated by scripts/generate_encoding_count.py.",
        "Each row equation is checked by the kernel, without native_decide. -/",
        "",
        "set_option maxRecDepth 2000",
        "set_option maxHeartbeats 1000000",
        "",
        "namespace XmssSecurity.TargetSum",
        "",
    ]
    row = [1] + [0] * 195
    for length in range(43):
        support_length = min(7 * length + 1, len(row))
        nonzero = row[:support_length]
        zero_count = len(row) - support_length
        lines.append(f"private def row{length} : List ℕ := [")
        for start in range(0, len(nonzero), 8):
            suffix = "," if start + 8 < len(nonzero) else "]"
            if start + 8 >= len(nonzero) and zero_count:
                suffix += f" ++ List.replicate {zero_count} 0"
            lines.append("  " + ", ".join(map(str, nonzero[start : start + 8])) + suffix)
        lines.extend(
            [
                "",
                f"private theorem row{length}_eq : countRow 8 195 {length} = row{length} := by",
            ]
        )
        if length:
            lines.append(f"  rw [countRow, row{length - 1}_eq]")
        lines.extend(["  decide +kernel", ""])
        if length < 42:
            row = [
                sum(row[total - digit] for digit in range(8) if digit <= total)
                for total in range(196)
            ]
    lines.extend(
        [
            "/-- The exact number of 42-digit radix-eight words with sum 195. -/",
            "theorem wordCount_eight_fortyTwo_195 :",
            f"    wordCount 8 42 195 = {row[195]} := by",
            "  rw [← countRow_getD_eq_wordCount 8 195 42 195 le_rfl, row42_eq]",
            "  decide +kernel",
            "",
            "end XmssSecurity.TargetSum",
            "",
        ]
    )
    return "\n".join(lines)


if __name__ == "__main__":
    destination = (
        Path(__file__).resolve().parents[1]
        / "XmssSecurity/Proof/EncodingCardinalityCertificate.lean"
    )
    destination.write_text(generate())
